#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, lo, hi, e;
    cin >> n >> lo >> hi >> e;
    const long long MOD = 1000000007;
    int w = hi - lo + 1;
    vector<long long> f(w, 0), g(w, 0);
    f[-lo] = 1;
    for (int t = 0; t < n; t++) {
        for (int i = 0; i < w; i++) {
            long long v = 0;
            if (i > 0) v += f[i - 1];
            if (i + 1 < w) v += f[i + 1];
            g[i] = v % MOD;
        }
        swap(f, g);
    }
    cout << f[e - lo] << '\n';
    return 0;
}
